const crypto = require('crypto');
const inputJson = $input.first().json;
const headers = inputJson.headers || {};
const sig = headers['x-signature'] || headers['X-Signature'];

let rawBody;
if (typeof inputJson.body === 'string') {
  rawBody = inputJson.body;
} else if (inputJson.body !== undefined) {
  rawBody = JSON.stringify(inputJson.body);
} else {
  rawBody = JSON.stringify(inputJson);
}

const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET not set');

const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
if (sig !== expected) throw new Error('invalid signature');

const parsed = typeof inputJson.body === 'string' ? JSON.parse(inputJson.body) : (inputJson.body || inputJson);
return [{ json: parsed }];

const d = $input.first().json.data || {};
const name = d.applicationName || 'طلبك';
const notes = d.supervisorNotes && String(d.supervisorNotes).trim() ? `\nالملاحظات: ${d.supervisorNotes}` : '';
let text;
switch (d.newStatus) {
  case 'accepted':
    text = `🎉 تمت الموافقة على طلبك "${name}".`;
    break;
  case 'rejected':
    text = `📝 طلبك "${name}" لم يُقبل.${notes}`;
    break;
  case 'needs_modification':
    text = `✏️ طلبك "${name}" يحتاج إلى تعديل.${notes}`;
    break;
  case 'under_review':
    text = `📂 طلبك "${name}" قيد المراجعة الآن.`;
    break;
  default:
    // Skip sending for unknown statuses by returning empty items
    return [];
}
const phone = $input.first().json.phone || '';
const to = (phone.startsWith('+') ? phone.slice(1) : phone) + '@s.whatsapp.net';
return [{ json: { to, text } }];
